(window.webpackJsonp=window.webpackJsonp||[]).push([[30],{384:function(t,e){"use strict";e.__esModule=!0,e.default={render:function(){return this.$createElement("div",{staticClass:"theme-default-content content__default lab-wide",domProps:{innerHTML:"\n<div class=\"lab-content join-page\">\r\n<h1 id=\"加入-mi2\"><a href=\"#加入-mi2\" class=\"header-anchor\">#</a> 加入 MI² Lab</h1>\r\n<section class=\"join-hero\"><p class=\"eyebrow\">硕士 · 博士 · 科研助理 · 实习生</p><h2>面向真实医学问题开展研究</h2><p>课题组长期欢迎对医学影像、计算机视觉和医工交叉感兴趣的学生与研究人员。研究从具体问题出发，重视方法设计、实验验证和临床合作。</p><div class=\"profile-actions\"><a class=\"button-secondary\" href=\"#申请流程\">查看申请方式</a></div></section>\n\r\n<h2 id=\"科研环境与培养\"><a href=\"#科研环境与培养\" class=\"header-anchor\">#</a> 科研环境与培养</h2>\n<div class=\"value-grid\"><article><strong>研究训练</strong><p>围绕明确问题完成文献调研、方法设计、实验分析和论文写作，形成完整的科研训练闭环。</p></article><article><strong>临床合作</strong><p>结合医学影像和临床数据，与医院及合作团队共同讨论问题、验证方法并分析结果。</p></article><article><strong>交流与发表</strong><p>鼓励开放讨论、代码实践和学术交流，支持在医学影像与人工智能领域的重要期刊和会议发表成果。</p></article></div>\n\r\n<h2 id=\"希望你是\"><a href=\"#希望你是\" class=\"header-anchor\">#</a> 希望你是</h2>\r\n<div class=\"candidate-layout\"><ul class=\"check-list\"><li>计划申请南京大学硕士、普通博士或直博项目。</li><li>具有计算机、生物医学工程、医学影像、临床医学、应用数学或相关专业背景。</li><li>对医学影像、计算机视觉、多模态大模型、医学智能体或医工交叉研究有明确兴趣。</li><li>具备良好的编程与数学基础；有论文成果或开源项目经验者优先。</li><li>做事踏实、重视合作，遇到问题主动沟通，愿意长期投入科研。</li></ul><aside><p class=\"eyebrow\">其他合作方式</p><p>也欢迎科研助理、实习生、访问学生，以及来自医院、影像中心和生命科学团队的合作者联系交流。</p></aside></div>\n\r\n<h2 id=\"招生信息\"><a href=\"#招生信息\" class=\"header-anchor\">#</a> 招生信息</h2>\r\n<div class=\"info-table\"><div><span>所在单位</span><strong>南京大学（苏州校区）生物医学工程学院</strong></div><div><span>招生导师</span><strong>张炯教授</strong></div><div><span>招生类型</span><strong>硕士 · 普通博士 · 直博</strong></div><div><span>招生名额</span><strong>以南京大学及学院当年招生计划为准</strong></div></div>\n\r\n<h2 id=\"申请流程\"><a href=\"#申请流程\" class=\"header-anchor\">#</a> 申请流程</h2>\r\n<div class=\"steps\"><div><span>1</span><h3>了解课题组</h3><p>阅读近期论文和项目成果，确认自己感兴趣的医学问题或技术方向。</p></div><div><span>2</span><h3>准备材料</h3><p>准备简短自我介绍、个人简历、成绩单和研究兴趣；如有论文、代码或项目，请附相关链接。</p></div><div><span>3</span><h3>发送邮件</h3><p>联系 <a href=\"mailto:lixiang.cog@smail.nju.edu.cn\">lixiang.cog@smail.nju.edu.cn</a>。正式申请按南京大学及学院最新通知执行。</p></div></div>\n<div class=\"team-callout application-callout\"><div><p class=\"eyebrow\">申请咨询</p><h3>邮件请注明申请方向和预计入学时间</h3><p>建议附个人简历、成绩单，以及代表性论文、代码或项目链接（如有）。</p></div><a class=\"button-primary\" href=\"mailto:lixiang.cog@smail.nju.edu.cn\">发送邮件</a></div>\n</div>"}})}}}}]);
